import {accountSession} from './account.js';
// The PIN opens a local copy. GitHub identity protects connection restoration.
export const PIN_HASH='7d12ba56e9f8b3dc64f77c87318c4f37bc12cfbf1a37573cdf3e4fa683f20155';
let locked=true,timer,resolveReady;
export const privacyReady=new Promise(resolve=>resolveReady=resolve);
export const isPrivacyLocked=()=>locked;
export function lockWorkspace(){locked=true;clearTimeout(timer);for(const id of ['dialogs','print-root','toasts'])document.getElementById(id)?.replaceChildren();document.body.classList.add('workspace-locked');document.getElementById('app').innerHTML=`<main class="privacy-screen"><form id="privacy-unlock" class="panel"><img src="./assets/ascend-mark.png" alt="Ascend" width="64" height="64"><span class="eyebrow">YOUR PRIVATE WORKSPACE</span><h1>Welcome back.</h1><p>Your next chapter, wherever you are.</p><div id="account-access" class="account-access" aria-live="polite"></div><label class="field"><span>Device password</span><input name="password" type="password" inputmode="numeric" autocomplete="current-password" required maxlength="80" autofocus></label><p id="privacy-error" role="alert"></p><button type="submit" class="btn secondary">Open saved device copy →</button><small>GitHub sign-in restores your workspace on a new browser. The device password opens the local copy.</small></form></main>`;document.getElementById('privacy-unlock').addEventListener('submit',unlock);document.querySelector('#privacy-unlock input')?.focus();showAccountAccess();window.dispatchEvent(new Event('ascend:lock'));}
async function showAccountAccess(){const session=await accountSession(true),el=document.querySelector('#account-access');if(!el||!locked||!session.configured)return;const action=document.createElement(session.authenticated?'button':'a');action.className='btn primary';if(session.authenticated){action.type='button';action.textContent='Open synced workspace';action.addEventListener('click',finishUnlock);}else{action.href='/api/account?mode=login';action.textContent='Sign in with GitHub';}const note=document.createElement('p');note.className='body-copy';const error=new URLSearchParams(location.search).get('account-error');note.textContent=error==='owner'?'This workspace belongs to your original GitHub account. Sign in with that account.':error?'GitHub sign-in did not finish. Please try again.':session.authenticated?'Your GitHub account is connected.':'No connection files needed. Your private workspace follows your account.';el.replaceChildren(action,note);}
function finishUnlock(){locked=false;document.body.classList.remove('workspace-locked');resolveReady();arm();window.dispatchEvent(new Event('ascend:unlock'));}
function arm(){clearTimeout(timer);if(!locked)timer=setTimeout(lockWorkspace,5*60*1000);}
async function unlock(e){e.preventDefault();const button=e.target.querySelector('button[type=submit]');button.disabled=true;try{const until=Number(localStorage.getItem('ascend.lock.until')||0);if(Date.now()<until)throw Error('Please wait '+Math.ceil((until-Date.now())/1000)+' seconds before trying again.');const value=new FormData(e.target).get('password');const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)))).map(x=>x.toString(16).padStart(2,'0')).join('');if(hash!==PIN_HASH){const fails=Number(localStorage.getItem('ascend.lock.failures')||0)+1;localStorage.setItem('ascend.lock.failures',String(fails));if(fails%5===0)localStorage.setItem('ascend.lock.until',String(Date.now()+30000));throw Error('That password is incorrect.');}localStorage.removeItem('ascend.lock.failures');localStorage.removeItem('ascend.lock.until');finishUnlock();}catch(error){document.getElementById('privacy-error').textContent=error.message;}finally{button.disabled=false;}}
document.addEventListener('pointerdown',arm,{passive:true});document.addEventListener('keydown',arm);let hiddenAt=0;document.addEventListener('visibilitychange',()=>{if(document.hidden)hiddenAt=Date.now();else if(hiddenAt&&Date.now()-hiddenAt>=5*60*1000)lockWorkspace();});
lockWorkspace();
